UPDATE outbox_message
SET status = 'PROCESSING',
    claimed_at = #{claimedAt}
WHERE id = #{id}
  AND status = 'PENDING'


UPDATE outbox_message
SET status = 'PROCESSING', claimed_at = CURRENT_TIMESTAMP, claim_token = #{token}
WHERE status = 'PENDING' AND created_at < #{cutoff}
ORDER BY created_at ASC
LIMIT #{batchSize}
